import{_ as t,o as d,c as a,a3 as o}from"./chunks/framework.cNy3aYYk.js";const g=JSON.parse('{"title":"Attendance department-scoped digests and list (1.6.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Attendance department-scoped digests and list (1.6.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/attendance-department-scoped-1-6-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Attendance department-scoped digests and list (1.6.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/attendance-department-scoped-1-6-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/attendance-department-scoped-1-6-0-production-readiness.md","filePath":"deployment/attendance-department-scoped-1-6-0-production-readiness.md","lastUpdated":1791282597000}'),n={name:"deployment/attendance-department-scoped-1-6-0-production-readiness.md"};function r(s,e,i,c,l,m){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="attendance-department-scoped-digests-and-list-1-6-0-—-production-readiness-audit" tabindex="-1">Attendance department-scoped digests and list (1.6.0) — Production Readiness Audit <a class="header-anchor" href="#attendance-department-scoped-digests-and-list-1-6-0-—-production-readiness-audit" aria-label="Permalink to &quot;Attendance department-scoped digests and list (1.6.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-10-03</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> (migrate catalog bump + smoke department manager scope)</td></tr><tr><td><strong>Scope</strong></td><td>Department-scoped attendance digests, list, KPIs, create/update; catalog <strong>attendance 1.5.0 → 1.6.0</strong></td></tr><tr><td><strong>Companion</strong></td><td><a href="./attendance">Attendance deployment</a> · <a href="/changelog/">CHANGELOG</a></td></tr></tbody></table><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Attendance visibility and daily digests no longer treat every Spatie <code>manager</code> as org-wide. <strong>Owners / Admins</strong> remain company-wide. Users assigned as <code>departments.manager_id</code> see and receive digests only for employees in their managed departments (<code>department_employee</code> ∪ employees linked via <code>department_user</code>, plus their own linked employee). Spatie <code>manager</code> without a department assignment is self-scoped and does not receive digests.</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> after migrate <code>2026_10_03_003500</code> and staging smoke with two department managers.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Platform freeze</td><td><strong>Pass</strong></td></tr><tr><td>Migrate-only catalog <strong>1.6.0</strong></td><td><strong>Pass</strong></td></tr><tr><td>Policy/list/stats/CRUD/delete scoped</td><td><strong>Pass</strong></td></tr><tr><td>Digests per-recipient scoped (claim after payload)</td><td><strong>Pass</strong></td></tr><tr><td>Analytics People attendance uses <code>visibleEmployeeIds</code></td><td><strong>Pass</strong></td></tr><tr><td>Pest attendance + analytics department scope</td><td><strong>Pass</strong> (local PHP 8.5)</td></tr><tr><td>Settings copy + Docs/CHANGELOG</td><td><strong>Pass</strong></td></tr><tr><td>Breaking: Spatie <code>manager</code> alone loses org-wide attendance</td><td><strong>Accepted</strong> (documented)</td></tr></tbody></table><hr><h2 id="audit-findings-resolved" tabindex="-1">Audit findings (resolved) <a class="header-anchor" href="#audit-findings-resolved" aria-label="Permalink to &quot;Audit findings (resolved)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Severity</th><th>Finding</th><th>Resolution</th></tr></thead><tbody><tr><td>High</td><td>Spatie <code>manager</code> org-wide break</td><td>Intentional; ops: assign dept manager or Admin</td></tr><tr><td>Medium</td><td>Own linked employee omitted from list</td><td><code>managedTeamEmployeeIds</code> unions own employee</td></tr><tr><td>Medium</td><td>delete/restore/forceDelete unscoped</td><td>Policy now requires <code>canAccessEmployee</code></td></tr><tr><td>Medium</td><td>Digest recipient N+1 <code>isDepartmentManager</code></td><td>Prefetch active <code>manager_id</code>s</td></tr><tr><td>Medium</td><td>Update request no employee gate</td><td><code>UpdateAttendanceRecordRequest</code> uses <code>canAccessEmployee</code></td></tr><tr><td>Medium</td><td>Analytics rule still said <code>canManageOthers</code></td><td><code>.ai/rules/tenant.md</code> updated</td></tr><tr><td>High (coverage)</td><td>Missing dept-user / analytics / cross-dept tests</td><td>Added and green</td></tr><tr><td>Low</td><td>Yesterday user-guide wording</td><td>Aligned with late-report recipient rules</td></tr></tbody></table><hr><h2 id="deploy-checklist" tabindex="-1">Deploy checklist <a class="header-anchor" href="#deploy-checklist" aria-label="Permalink to &quot;Deploy checklist&quot;">​</a></h2><ol><li>Deploy Backend + Frontend + Docs from <code>feature/attendance-department-scoped-reports</code>.</li><li>Migrate: <code>php artisan migrate --force</code> through <code>2026_10_03_003500</code> (<strong>attendance → 1.6.0</strong>).</li><li>Confirm <code>attendance:send-daily-reports</code> schedule + <code>emails</code> queue workers.</li><li>Smoke: <ul><li>Two departments, each with a manager and late employees → manager A only sees/receives A; Owner sees all</li><li>Spatie <code>manager</code> without <code>manager_id</code> → self list only; no digest</li><li>Department manager with <code>department_user</code> membership (linked employee) included in scope</li></ul></li><li>Pest: <code>AttendanceDailyReportDigestTest</code>, <code>AttendanceTest</code> department cases, people analytics department scope, <code>AttendanceModuleVersion160BumpTest</code>.</li></ol><hr><h2 id="residual-risk" tabindex="-1">Residual risk <a class="header-anchor" href="#residual-risk" aria-label="Permalink to &quot;Residual risk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Notes</th></tr></thead><tbody><tr><td>Orgs relying on role-only managers for company attendance</td><td>Must assign Admin or department <code>manager_id</code></td></tr><tr><td>Empty-team department managers</td><td>Digests skip when scoped payload empty; list may show only self</td></tr></tbody></table><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Status</th></tr></thead><tbody><tr><td>Engineering</td><td><strong>Go</strong></td></tr><tr><td>Staging smoke (two dept managers)</td><td>Recommended before wide rollout</td></tr></tbody></table>',19)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
